using System;using System.IO;using ScoreModern.RecoveredFragments;
class RasterFlagsRuntimeProof {
 class Memory:IHorizontalRasterMemory {public byte[] Data,Plane;public ushort DS,ES;public ushort ReadWord(ushort s,ushort o){if(s!=DS)throw new Exception("DS");return (ushort)(Data[o]|Data[(ushort)(o+1)]<<8);}public void WriteWord(ushort s,ushort o,ushort v){if(s!=DS)throw new Exception("DS");Data[o]=(byte)v;Data[(ushort)(o+1)]=(byte)(v>>8);}public void OrByte(ushort s,ushort o,byte mask){if(s!=ES)throw new Exception("ES");Plane[o]|=mask;}}
 static ushort H(string s){return Convert.ToUInt16(s,16);}static string Show(VerticalRasterWords r){return r.AX+":"+r.BX+":"+r.CX+":"+r.DX+":"+r.SI+":"+r.DI+":"+r.BP+":"+r.EFlags;}
 static int Main(string[] a){try{string mode=a[0],p=a[1];Memory m=new Memory{DS=H(a[2]),ES=H(a[3]),Data=File.ReadAllBytes(Path.Combine(p,"raster-before-ds.bin")),Plane=File.ReadAllBytes(Path.Combine(p,"raster-before-plane2.bin"))};ushort ax=H(a[4]),bx=H(a[5]),cx=H(a[6]),dx=H(a[7]),si=H(a[8]);uint flags=Convert.ToUInt32(a[9],16);VerticalRasterWords result=mode=="V"?VerticalRaster.ExecuteWithFlags(m,m.DS,m.ES,ax,bx,cx,dx,flags):mode=="S"?SlopedRaster.ExecuteWithFlags(m,m.DS,m.ES,ax,bx,cx,dx,flags):EqualStepRaster.ExecuteWithFlags(m,m.DS,m.ES,ax,cx,dx,si,flags);VerticalRasterWords expected=new VerticalRasterWords{AX=H(a[10]),BX=H(a[11]),CX=H(a[12]),DX=H(a[13]),SI=H(a[14]),DI=H(a[15]),BP=H(a[16]),EFlags=Convert.ToUInt32(a[17],16)};if(Show(result)!=Show(expected)||result.DefinedEFlagsMask!=0xffffffffu)throw new Exception("Full flags/words "+Show(result)+" != "+Show(expected));byte[] after=File.ReadAllBytes(Path.Combine(p,"raster-after-ds.bin")),plane=File.ReadAllBytes(Path.Combine(p,"raster-after-plane2.bin"));if(m.Data.Length!=65536||m.Plane.Length!=65536||after.Length!=65536||plane.Length!=65536)throw new Exception("Length");for(int i=0;i<65536;i++)if(m.Data[i]!=after[i]||m.Plane[i]!=plane[i])throw new Exception("Memory");Console.WriteLine("PASS original "+mode+" raster full EFLAGS, seven result words and 131072 DS/plane view bytes.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
